function characterReplacement(s, k) {
  let maxLen = 0;
  const n = s.length;

  for (let i = 0; i < n; i++) {
    const counts = {};
    let maxFreq = 0;

    for (let j = i; j < n; j++) {
      const ch = s[j];
      counts[ch] = (counts[ch] || 0) + 1;
      if (counts[ch] > maxFreq) {
        maxFreq = counts[ch];
      }

      const windowLen = j - i + 1;
      if (windowLen - maxFreq <= k) {
        if (windowLen > maxLen) {
          maxLen = windowLen;
        }
      }
    }
  }

  return maxLen;
}

